<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { createSlaPolicy, fetchSlaPage, fetchSlaPolicy, updateSlaPolicy } from '@/services/sla'
import type { SlaPolicy } from '@/types/api'
const rows = ref<SlaPolicy[]>([]); const visible = ref(false); const editing = ref(false); const loading = ref(false)
const form = reactive({ id: 0, policyName: '', priority: 'P2' as 'P0'|'P1'|'P2', responseMinutes: 60, resolutionMinutes: 480, enabled: true, version: 0 })
async function load() { loading.value = true; try { rows.value = (await fetchSlaPage({ pageNum: 1, pageSize: 100 })).records } finally { loading.value = false } }
function openCreate() { editing.value = false; Object.assign(form, { id: 0, policyName: '', priority: 'P2', responseMinutes: 60, resolutionMinutes: 480, enabled: true, version: 0 }); visible.value = true }
async function openEdit(value: unknown) { const row = value as SlaPolicy; editing.value = true; Object.assign(form, await fetchSlaPolicy(row.id)); visible.value = true }
async function save() { if (!form.policyName) return ElMessage.warning('策略名称不能为空'); if (editing.value) await updateSlaPolicy({ id: form.id, policyName: form.policyName, responseMinutes: form.responseMinutes, resolutionMinutes: form.resolutionMinutes, enabled: form.enabled, version: form.version }); else await createSlaPolicy({ policyName: form.policyName, priority: form.priority, responseMinutes: form.responseMinutes, resolutionMinutes: form.resolutionMinutes }); visible.value = false; ElMessage.success('SLA 策略已保存'); await load() }
onMounted(load)
</script>
<template><main class="workspace-page"><header class="page-heading"><div><span class="section-kicker">SERVICE LEVEL</span><h1>SLA 策略</h1><p>按优先级设置首次响应和解决时限。</p></div><el-button class="primary-action" type="primary" @click="openCreate">新增策略</el-button></header><section class="glass-card module-card"><el-table v-loading="loading" :data="rows"><el-table-column prop="policyName" label="策略" /><el-table-column prop="priority" label="优先级" /><el-table-column prop="responseMinutes" label="响应分钟" /><el-table-column prop="resolutionMinutes" label="解决分钟" /><el-table-column label="状态"><template #default="scope"><el-tag :type="scope.row.enabled?'success':'info'">{{ scope.row.enabled?'启用':'停用' }}</el-tag></template></el-table-column><el-table-column prop="version" label="版本" /><el-table-column label="操作"><template #default="scope"><el-button link @click="openEdit(scope.row)">编辑</el-button></template></el-table-column></el-table></section><el-dialog v-model="visible" :title="editing?'编辑 SLA':'新增 SLA'" width="520px"><el-form label-position="top"><el-form-item label="策略名称"><el-input v-model="form.policyName" /></el-form-item><el-form-item label="优先级"><el-select v-model="form.priority" :disabled="editing"><el-option v-for="item in ['P0','P1','P2']" :key="item" :value="item" /></el-select></el-form-item><div class="form-grid"><el-form-item label="响应分钟"><el-input-number v-model="form.responseMinutes" :min="1" /></el-form-item><el-form-item label="解决分钟"><el-input-number v-model="form.resolutionMinutes" :min="1" /></el-form-item></div><el-form-item v-if="editing" label="是否启用"><el-switch v-model="form.enabled" /></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></main></template>
